Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
hisi_sas: fix v1 hw check for slot error

Completion header bit CMPLT_HDR_RSPNS_XFRD flags whether the response
frame is received into host memory, and not whether the response frame
has an error.  As such, change the decision on whether a slot has an
error.  Also redundant check on CMPLT_HDR_CMD_CMPLT_MSK is removed.

Fixes: 27a3f229 ("hisi_sas: Add cq interrupt handler")

Signed-off-by: John Garry <john.garry@huawei.com>
Tested-by: Ricardo Salveti <ricardo.salveti@linaro.org>
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>

Here is the root cause:
The bug was caused by an incorrect conditional check in the error handling logic for slot completion. The original implementation mistakenly used both `CMPLT_HDR_CMD_CMPLT_MSK` and `CMPLT_HDR_RSPNS_XFRD_MSK` to determine if a slot had an error, leading to incorrect error detection. The check should have only considered whether the response frame was received into host memory, as indicated by `CMPLT_HDR_RSPNS_XFRD_MSK`, while also checking for the error record flag `CMPLT_HDR_ERR_RCRD_XFRD_MSK`.

Here is the patch:

 static int slot_complete_v1_hw(struct hisi_hba *hisi_hba,
 			       struct hisi_sas_slot *slot, int abort)
 {
 	struct sas_task *task = slot->task;
 	struct hisi_sas_device *sas_dev;
 	struct device *dev = &hisi_hba->pdev->dev;
 	struct task_status_struct *ts;
 	struct domain_device *device;
 	enum exec_status sts;
 	struct hisi_sas_complete_v1_hdr *complete_queue =
 			(struct hisi_sas_complete_v1_hdr *)
 			hisi_hba->complete_hdr[slot->cmplt_queue];
 	struct hisi_sas_complete_v1_hdr *complete_hdr;
 	u32 cmplt_hdr_data;

 	complete_hdr = &complete_queue[slot->cmplt_queue_slot];
 	cmplt_hdr_data = le32_to_cpu(complete_hdr->data);

 	if (unlikely(!task || !task->lldd_task || !task->dev))
 		return -EINVAL;

 	ts = &task->task_status;
 	device = task->dev;
 	sas_dev = device->lldd_dev;

 	task->task_state_flags &=
 		~(SAS_TASK_STATE_PENDING | SAS_TASK_AT_INITIATOR);
 	task->task_state_flags |= SAS_TASK_STATE_DONE;

 	memset(ts, 0, sizeof(*ts));
 	ts->resp = SAS_TASK_COMPLETE;

 	if (unlikely(!sas_dev || abort)) {
 		if (!sas_dev)
 			dev_dbg(dev, "slot complete: port has not device\n");
 		ts->stat = SAS_PHY_DOWN;
 		goto out;
 	}

 	if (cmplt_hdr_data & CMPLT_HDR_IO_CFG_ERR_MSK) {
 		u32 info_reg = hisi_sas_read32(hisi_hba, HGC_INVLD_DQE_INFO);

 		if (info_reg & HGC_INVLD_DQE_INFO_DQ_MSK)
 			dev_err(dev, "slot complete: [%d:%d] has dq IPTT err",
 				slot->cmplt_queue, slot->cmplt_queue_slot);

 		if (info_reg & HGC_INVLD_DQE_INFO_TYPE_MSK)
 			dev_err(dev, "slot complete: [%d:%d] has dq type err",
 				slot->cmplt_queue, slot->cmplt_queue_slot);

 		if (info_reg & HGC_INVLD_DQE_INFO_FORCE_MSK)
 			dev_err(dev, "slot complete: [%d:%d] has dq force phy err",
 				slot->cmplt_queue, slot->cmplt_queue_slot);

 		if (info_reg & HGC_INVLD_DQE_INFO_PHY_MSK)
 			dev_err(dev, "slot complete: [%d:%d] has dq phy id err",
 				slot->cmplt_queue, slot->cmplt_queue_slot);

 		if (info_reg & HGC_INVLD_DQE_INFO_ABORT_MSK)
 			dev_err(dev, "slot complete: [%d:%d] has dq abort flag err",
 				slot->cmplt_queue, slot->cmplt_queue_slot);

 		if (info_reg & HGC_INVLD_DQE_INFO_IPTT_OF_MSK)
 			dev_err(dev, "slot complete: [%d:%d] has dq IPTT or ICT err",
 				slot->cmplt_queue, slot->cmplt_queue_slot);

 		if (info_reg & HGC_INVLD_DQE_INFO_SSP_ERR_MSK)
 			dev_err(dev, "slot complete: [%d:%d] has dq SSP frame type err",
 				slot->cmplt_queue, slot->cmplt_queue_slot);

 		if (info_reg & HGC_INVLD_DQE_INFO_OFL_MSK)
 			dev_err(dev, "slot complete: [%d:%d] has dq order frame len err",
 				slot->cmplt_queue, slot->cmplt_queue_slot);

 		ts->stat = SAS_OPEN_REJECT;
 		ts->open_rej_reason = SAS_OREJ_UNKNOWN;
 		goto out;
 	}

-	if (cmplt_hdr_data & CMPLT_HDR_ERR_RCRD_XFRD_MSK) {
-		if (!(cmplt_hdr_data & CMPLT_HDR_CMD_CMPLT_MSK) ||
-		    !(cmplt_hdr_data & CMPLT_HDR_RSPNS_XFRD_MSK))
-			ts->stat = SAS_DATA_OVERRUN;
-		else
-			slot_err_v1_hw(hisi_hba, task, slot);
+	if (cmplt_hdr_data & CMPLT_HDR_ERR_RCRD_XFRD_MSK &&
+		!(cmplt_hdr_data & CMPLT_HDR_RSPNS_XFRD_MSK)) {

+		slot_err_v1_hw(hisi_hba, task, slot);
 		goto out;
 	}

 	switch (task->task_proto) {
 	case SAS_PROTOCOL_SSP:
 	{
 		struct ssp_response_iu *iu = slot->status_buffer +
 			sizeof(struct hisi_sas_err_record);
 		sas_ssp_task_response(dev, task, iu);
 		break;
 	}
 	case SAS_PROTOCOL_SMP:
 	{
 		void *to;
 		struct scatterlist *sg_resp = &task->smp_task.smp_resp;

 		ts->stat = SAM_STAT_GOOD;
 		to = kmap_atomic(sg_page(sg_resp));

 		dma_unmap_sg(dev, &task->smp_task.smp_resp, 1,
 			     DMA_FROM_DEVICE);
 		dma_unmap_sg(dev, &task->smp_task.smp_req, 1,
 			     DMA_TO_DEVICE);
 		memcpy(to + sg_resp->offset,
 		       slot->status_buffer +
 		       sizeof(struct hisi_sas_err_record),
 		       sg_dma_len(sg_resp));
 		kunmap_atomic(to);
 		break;
 	}
 	case SAS_PROTOCOL_SATA:
 	case SAS_PROTOCOL_STP:
 	case SAS_PROTOCOL_SATA | SAS_PROTOCOL_STP:
 		dev_err(dev, "slot complete: SATA/STP not supported");
 		break;

 	default:
 		ts->stat = SAM_STAT_CHECK_CONDITION;
 		break;
 	}

 	if (!slot->port->port_attached) {
 		dev_err(dev, "slot complete: port %d has removed\n",
 			slot->port->sas_port.id);
 		ts->stat = SAS_PHY_DOWN;
 	}

 out:
 	if (sas_dev && sas_dev->running_req)
 		sas_dev->running_req--;

 	hisi_sas_slot_task_free(hisi_hba, task, slot);
 	sts = ts->stat;

 	if (task->task_done)
 		task->task_done(task);

 	return sts;
 }



